import java.util.HashMap;
import java.util.Scanner;

public class Vokabeltrainer {

    public static void main(String[] args) {
        HashMap<String, String> vokabeln = new HashMap<>();
        vokabeln.put("Hund", "dog");
        vokabeln.put("Katze", "cat");
        vokabeln.put("Haus", "house");

        Scanner scanner = new Scanner(System.in);
        int punkte = 0;

        System.out.println("Was heißt Hund?");
        String antwort1 = scanner.nextLine();
        if (antwort1.equals(vokabeln.get("Hund"))) {
            punkte++;
        } else {
            System.out.println("Falsch, richtig wäre: " + vokabeln.get("Hund"));
        }

        System.out.println("Was heißt Katze?");
        String antwort2 = scanner.nextLine();
        if (antwort2.equals(vokabeln.get("Katze"))) {
            punkte++;
        } else {
            System.out.println("Falsch, richtig wäre: " + vokabeln.get("Katze"));
        }

        System.out.println("Was heißt Haus?");
        String antwort3 = scanner.nextLine();
        if (antwort3.equals(vokabeln.get("Haus"))) {
            punkte++;
        } else {
            System.out.println("Falsch, richtig wäre: " + vokabeln.get("Haus"));
        }

        int quote = punkte * 100 / 3;
        System.out.println("Ergebnis: " + punkte + " von 3");
        System.out.println("Quote: " + quote + "%");
    }
}
